import sys
from math import gcd

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    for _ in range(T):
        try:
            N = int(next(iterator))
            M = int(next(iterator))
        except StopIteration:
            break

        adj = [[] for _ in range(N + 1)]
        for _ in range(M):
            u = int(next(iterator))
            v = int(next(iterator))
            adj[u].append(v)
            adj[v].append(u)

        S = [0] * (N + 1)

        for start_node in range(1, N + 1):
            best_sum_for_max_len = -1
            max_len = -1

            stack = [(start_node, {start_node}, start_node)]

            while stack:
                curr, visited, current_sum = stack.pop()

                path_len = len(visited)

                if path_len > max_len:
                    max_len = path_len
                    best_sum_for_max_len = current_sum
                elif path_len == max_len:
                    if current_sum > best_sum_for_max_len:
                        best_sum_for_max_len = current_sum

                for neighbor in adj[curr]:
                    if neighbor not in visited:
                        new_visited = visited | {neighbor}
                        stack.append((neighbor, new_visited, current_sum + neighbor))

            if max_len == -1:
                S[start_node] = start_node
            else:
                S[start_node] = best_sum_for_max_len

        A = min(S[1:])
        B = max(S[1:])

        common = gcd(A, B)
        x = B // common
        y = A // common

        print(f"{x} {y}")

if __name__ == "__main__":
    solve()
